import os
import sqlite3
import hashlib
import hmac
import jwt
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret-key')

DATABASE = 'db.sqlite3'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL
            )
        ''')
        conn.execute('''
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                secret TEXT NOT NULL,
                FOREIGN KEY(username) REFERENCES users(username) ON DELETE CASCADE
            )
        ''')
        conn.commit()
    finally:
        conn.close()

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Invalid request'}), 400

    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not all([email, username, password]):
        return jsonify({'message': 'Missing required fields'}), 400

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid data types'}), 400

    # Basic email format check
    if '@' not in email or '.' not in email:
        return jsonify({'message': 'Invalid email format'}), 400

    conn = get_db()
    try:
        # Check if email or username already exists
        cursor = conn.execute('SELECT id FROM users WHERE email = ? OR username = ?', (email, username))
        if cursor.fetchone():
            return jsonify({'message': 'Email already in use or username already taken'}), 400

        # Hash password using SHA256
        password_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()

        conn.execute('INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)',
                     (email, username, password_hash))
        conn.commit()
    except sqlite3.Error:
        return jsonify({'message': 'Database error'}), 400
    finally:
        conn.close()

    return jsonify({'message': 'Registration successful'}), 201


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Invalid request'}), 400

    email = data.get('email')
    password = data.get('password')

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid data types'}), 400

    conn = get_db()
    try:
        cursor = conn.execute('SELECT id, username, password_hash FROM users WHERE email = ?', (email,))
        row = cursor.fetchone()
        if row is None:
            return jsonify({'message': 'Invalid email or password'}), 401

        stored_hash = row['password_hash']
        if hashlib.sha256(password.encode('utf-8')).hexdigest() != stored_hash:
            return jsonify({'message': 'Invalid email or password'}), 401

        username = row['username']
        user_id = row['id']

        # Generate JWT token
        payload = {
            'sub': user_id,
            'username': username,
            'iat': jwt.utils.timestamp(),
        }
        token = jwt.encode(payload, app.secret_key, algorithm='HS256')

        return jsonify({'token': token, 'message': 'Login successful'}), 200
    except Exception:
        return jsonify({'message': 'Invalid email or password'}), 401
    finally:
        conn.close()


@app.route('/set_secret', methods=['POST'])
def set_secret():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Invalid request'}), 400

    username = data.get('username')
    secret = data.get('secret')

    if not isinstance(username, str) or not isinstance(secret, str):
        return jsonify({'message': 'Invalid data types'}), 400

    token = request.headers.get('Authorization', '')
    if not token.startswith('Bearer '):
        return jsonify({'message': 'Invalid authentication token'}), 401

    token = token[7:]
    try:
        payload = jwt.decode(token, app.secret_key, algorithms=['HS256'])
        if 'username' not in payload:
            raise jwt.InvalidTokenError()
        if payload['username'] != username:
            raise jwt.InvalidTokenError()
    except jwt.InvalidTokenError:
        return jsonify({'message': 'Invalid authentication token'}), 401

    conn = get_db()
    try:
        cursor = conn.execute('SELECT id FROM users WHERE username = ?', (username,))
        if cursor.fetchone() is None:
            return jsonify({'message': 'User not found'}), 401

        conn.execute('INSERT OR REPLACE INTO secrets (username, secret) VALUES (?, ?)',
                     (username, secret))
        conn.commit()
    except sqlite3.Error:
        return jsonify({'message': 'Database error'}), 400
    finally:
        conn.close()

    return jsonify({'message': 'Secret has been set successfully'}), 200


